tail -50 /data3/paper_analysis/paper_extract_checkpoints/system_model_codesign/logs/010__SLA2.stream.jsonl 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try:
        obj = json.loads(line)
        t = obj.get('type','')
        if t == 'user':
            print('USER:', json.dumps(obj.get('message',''), ensure_ascii=False)[:500])
        elif t == 'assistant':
            print('ASSISTANT:', json.dumps(obj.get('message',''), ensure_ascii=False)[:500])
        elif t == 'stream_event':
            delta = obj.get('event',{}).get('delta',{})
            if 'text_delta' in delta:
                print('TEXT:', delta['text_delta'][:300])
        elif t == 'tool_result':
            print('TOOL_RESULT:', obj.get('tool_use_id','')[:50])
        elif t == 'tool_use':
            print('TOOL_USE:', obj.get('tool_name',''), obj.get('tool_use_id','')[:20])
        else:
            print(t.upper())
    except:
        pass
" 2>&1 | tail -80
